import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";

// Count maintained files, including new files, without entering generated output.
// The npm lockfile is generated by npm; all handwritten source/configuration is checked.
const files = execFileSync("git", ["ls-files", "-z", "--cached", "--others", "--exclude-standard"], {
  encoding: "utf8",
}).split("\0");
const failures: string[] = [];
for (const file of new Set(files)) {
  if (file === "package-lock.json" || !/\.(?:[cm]?[jt]sx?|css|json|ya?ml|html)$/u.test(file) || !existsSync(file))
    continue;
  const text = readFileSync(file, "utf8");
  const lines = text.split("\n").length - Number(text.endsWith("\n"));
  if (lines > 299) failures.push(`${file}: ${lines} physical lines (maximum 299)`);
}
if (failures.length) {
  console.error(failures.join("\n"));
  process.exitCode = 1;
} else {
  console.log("Handwritten source and configuration meet the 299-line limit.");
}
